/**
 * Iyye's own SearXNG (plan 0.004 T3): a self-hosted metasearch server, run
 * and watched by the host like Hindsight and Kev. No account and no API key:
 * it queries public engines itself.
 *
 * - Served by granian (SearXNG's production server, in its server
 *   requirements) from the pinned source tree `web/searxng` with the
 *   requirements in `web/.venv`.
 * - `settings.yml` is generated by the host on every start: 127.0.0.1 only,
 *   a random secret key (0600 file), the limiter, image proxy and metrics
 *   off, JSON results on, safe search on, and only the engines that worked
 *   from this machine (`IYYE2_SEARXNG_ENGINES`; plan 0.004 T0).
 * - Its environment is built from scratch: nothing from the host's leaks in.
 * - It has no authentication of its own: it listens on 127.0.0.1 only, and a
 *   model can never reach it through `web_fetch` (the guarded client refuses
 *   local addresses). Only `web_search` queries it, through a URL the host builds.
 */

import { randomBytes } from "node:crypto";
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { Logger } from "../log.ts";
import { SupervisedProcess } from "../process/supervised.ts";

export type SearxngState = "disabled" | "not installed" | "starting" | "up" | "retrying" | "stopped";

export interface SearxngStatus {
	state: SearxngState;
	detail: string;
}

export interface SearxngOptions {
	/** `iyye_2/web`: holds `searxng/` (the source tree) and `.venv/`. */
	installDir: string;
	/** `<IYYE2_STATE_DIR>/web`: settings, secret, logs, pid file. */
	stateDir: string;
	port: number;
	engines: string[];
	log: Logger;
	enabled?: boolean;
	healthIntervalMs?: number;
	startTimeoutMs?: number;
	restartBackoffMs?: number[];
	/** Tests: a fake server; defaults to granian serving `searx.webapp:app`. */
	command?: string[];
}

export interface SearchHit {
	title: string;
	url: string;
	snippet: string;
	engines: string[];
}

export class SearxngService {
	private readonly o: Required<Omit<SearxngOptions, "command">> & { command: string[] };
	private readonly proc: SupervisedProcess;
	private current: SearxngStatus = { state: "stopped", detail: "not started" };
	private running = false;
	private loop: Promise<void> = Promise.resolve();
	private wake: (() => void) | null = null;

	constructor(opts: SearxngOptions) {
		this.o = {
			enabled: true,
			healthIntervalMs: 30_000,
			startTimeoutMs: 60_000,
			restartBackoffMs: [5000, 30_000, 120_000],
			...opts,
			command: opts.command ?? [
				join(opts.installDir, ".venv", "bin", "granian"),
				"--interface",
				"wsgi",
				"--workers",
				"1",
				"searx.webapp:app",
			],
		};
		const [command, ...rest] = this.o.command;
		this.proc = new SupervisedProcess({
			name: "searxng",
			command: command!,
			args: [...rest, "--host", "127.0.0.1", "--port", String(opts.port)],
			env: () => this.env(),
			port: opts.port,
			stateDir: opts.stateDir,
			healthUrl: `${this.baseUrl}/healthz`,
			// granian renames its process to "granian wsgi 127.0.0.1:<port> searx.webapp:app"; both forms carry these.
			identity: [rest.at(-1) ?? command!, String(opts.port)],
			startTimeoutMs: this.o.startTimeoutMs,
			stopGraceMs: 10_000,
			log: opts.log,
		});
	}

	get status(): SearxngStatus {
		return this.current;
	}

	get baseUrl(): string {
		return `http://127.0.0.1:${this.o.port}`;
	}

	get up(): boolean {
		return this.current.state === "up";
	}

	start(): void {
		if (this.running) return;
		if (!this.o.enabled) {
			this.set("disabled", "IYYE2_WEB_ENABLED=0");
			return;
		}
		if (!existsSync(this.o.command[0]!) || !existsSync(join(this.o.installDir, "searxng", "searx"))) {
			this.set(
				"not installed",
				`missing ${join(this.o.installDir, ".venv")} or ${join(this.o.installDir, "searxng")}`,
			);
			return;
		}
		this.running = true;
		mkdirSync(this.o.stateDir, { recursive: true, mode: 0o700 });
		this.loop = this.supervise();
	}

	async stop(): Promise<void> {
		this.running = false;
		this.wake?.();
		await this.loop;
		await this.proc.stop();
		if (this.current.state !== "disabled" && this.current.state !== "not installed") this.set("stopped", "stopped");
	}

	/** Search; throws when SearXNG is not up or answers badly. The URL is built here, never by a model. */
	async search(query: string, opts: { language?: string; timeoutMs?: number } = {}): Promise<SearchHit[]> {
		if (!this.up) throw new Error(`SearXNG is ${this.current.state}`);
		const params = new URLSearchParams({ q: query, format: "json", safesearch: "1" });
		if (opts.language) params.set("language", opts.language);
		const res = await fetch(`${this.baseUrl}/search?${params}`, {
			signal: AbortSignal.timeout(opts.timeoutMs ?? 15_000),
		});
		if (!res.ok) throw new Error(`SearXNG answered HTTP ${res.status}`);
		const body = (await res.json()) as {
			results?: { title?: string; url?: string; content?: string; engines?: string[] }[];
		};
		return (body.results ?? [])
			.filter((r) => typeof r.url === "string" && /^https?:\/\//.test(r.url))
			.map((r) => ({
				title: String(r.title ?? ""),
				url: r.url!,
				snippet: String(r.content ?? ""),
				engines: Array.isArray(r.engines) ? r.engines.map(String) : [],
			}));
	}

	/** The settings file SearXNG runs with (exposed for tests). */
	settingsYaml(): string {
		const names = this.o.engines.map((e) => JSON.stringify(e)).join(", ");
		return [
			"# Generated by the Iyye host on every start (plan 0.004 T3); edits are overwritten.",
			"use_default_settings:",
			"  engines:",
			`    keep_only: [${names}]`,
			"general:",
			"  instance_name: iyye",
			"  enable_metrics: false",
			"server:",
			'  bind_address: "127.0.0.1"',
			`  port: ${this.o.port}`,
			`  secret_key: ${JSON.stringify(this.secret())}`,
			"  limiter: false",
			"  image_proxy: false",
			"  public_instance: false",
			"search:",
			"  formats: [html, json]",
			"  safe_search: 1",
			"engines:",
			...this.o.engines.flatMap((e) => [`  - name: ${JSON.stringify(e)}`, "    disabled: false"]),
			"",
		].join("\n");
	}

	/** The exact environment SearXNG runs with (exposed for tests). */
	env(): Record<string, string> {
		const home = join(this.o.stateDir, "home");
		mkdirSync(home, { recursive: true });
		const settings = join(this.o.stateDir, "settings.yml");
		writeFileSync(settings, this.settingsYaml(), { mode: 0o600 });
		chmodSync(settings, 0o600);
		return {
			PATH: "/usr/bin:/bin",
			HOME: home,
			SEARXNG_SETTINGS_PATH: settings,
			PYTHONPATH: join(this.o.installDir, "searxng"),
		};
	}

	// ---------------------------------------------------------------- internals

	private secret(): string {
		const file = join(this.o.stateDir, "secrets", "searxng_secret");
		if (!existsSync(file)) {
			mkdirSync(join(this.o.stateDir, "secrets"), { recursive: true, mode: 0o700 });
			writeFileSync(file, randomBytes(32).toString("hex"), { mode: 0o600 });
		}
		return readFileSync(file, "utf8").trim();
	}

	private async supervise(): Promise<void> {
		let failures = 0;
		while (this.running) {
			try {
				if (!(await this.healthy())) {
					this.set("starting", failures === 0 ? "starting SearXNG" : "restarting");
					await this.bringUp();
				}
				failures = 0;
				this.set("up", `SearXNG on 127.0.0.1:${this.o.port} (${this.o.engines.join(", ")})`);
				await this.pause(this.o.healthIntervalMs);
			} catch (err) {
				if (!this.running) break;
				failures++;
				const backoff = this.o.restartBackoffMs[Math.min(failures - 1, this.o.restartBackoffMs.length - 1)]!;
				this.set("retrying", `${(err as Error).message}; retrying in ${Math.round(backoff / 1000)} s`);
				await this.pause(backoff);
			}
		}
	}

	private async bringUp(): Promise<void> {
		if (this.proc.isAlive() || this.proc.tryAdopt()) {
			// Adopted after a host crash: keep it only if it is ours (instance name) and healthy.
			if (await this.healthy()) return;
			this.o.log.warn("web: running SearXNG is not Iyye's; restarting it");
			await this.proc.stop();
		}
		await this.proc.start();
		if (!(await this.healthy())) throw new Error("SearXNG started but is not Iyye's instance");
	}

	private async healthy(): Promise<boolean> {
		if (!this.proc.isAlive()) return false;
		try {
			const res = await fetch(`${this.baseUrl}/config`, { signal: AbortSignal.timeout(5000) });
			if (!res.ok) {
				await res.body?.cancel();
				return false;
			}
			const cfg = (await res.json()) as { instance_name?: string };
			return cfg.instance_name === "iyye";
		} catch {
			return false;
		}
	}

	private pause(ms: number): Promise<void> {
		return new Promise<void>((resolve) => {
			const done = () => {
				clearTimeout(timer);
				this.wake = null;
				resolve();
			};
			const timer = setTimeout(done, ms);
			timer.unref();
			this.wake = done;
		});
	}

	private set(state: SearxngState, detail: string): void {
		if (this.current.state !== state || this.current.detail !== detail) {
			this.o.log[state === "retrying" ? "warn" : "info"](`web: ${state}`, { detail });
		}
		this.current = { state, detail };
	}
}
